def norm(name:str)->str:
    name=name.strip().replace(' ,', ',')
    # collapse spaces
    name=re.sub(r'\\s+', ' ', name)
    # smart title case for ALLCAPS names while preserving initials/punctuation
    if name.upper()==name:
        parts=[]
        for tok in name.split(' '):
            if tok in {'JR.', 'SR.'}:
                parts.append(tok.title())
            elif re.fullmatch(r'[A-Z]\\.', tok) or re.fullmatch(r'[A-Z]\\.[A-Z]\\.?', tok) or re.fullmatch(r'[A-Z]\\.[A-Z]\\.[A-Z]\\.?', tok):
                parts.append(tok)
            else:
                parts.append(tok.title())
        name=' '.join(parts)
    return name

